private Map<ModelPos, PartData> createQuads(Object2BooleanMap<ModuleModelSpec> modules, Set<EquipmentSlot> wornParts, boolean hasMekaToolLeft, boolean hasMekaToolRight) {
        Map<OBJModelData, Map<ModelPos, Set<String>>> specialQuadsToRender = new Object2ObjectOpenHashMap<>();
        // map of normal model part name to overwritten model part name (i.e. helmet_head_center1 -> override_solar_helmet_helmet_head_center1)
        Map<String, OverrideData> overrides = new Object2ObjectOpenHashMap<>();
        Set<String> ignored = new HashSet<>();

        if (!modules.isEmpty()) {
            Map<OBJModelData, Set<String>> allMatchedParts = new Object2ObjectOpenHashMap<>();
            for (ModuleOBJModelData modelData : MekanismModelCache.INSTANCE.MEKASUIT_MODULES) {
                Set<String> matchedParts = allMatchedParts.computeIfAbsent(modelData, _ -> new HashSet<>());
                for (ObjectIterator<Object2BooleanMap.Entry<ModuleModelSpec>> iterator = Object2BooleanMaps.fastIterator(modules); iterator.hasNext(); ) {
                    Object2BooleanMap.Entry<ModuleModelSpec> entry = iterator.next();
                    ModuleModelSpec spec = entry.getKey();
                    for (String name : modelData.getPartsForSpec(spec, entry.getBooleanValue())) {
                        if (name.contains(OVERRIDDEN_TAG)) {
                            overrides.put(spec.processOverrideName(name), new OverrideData(modelData, name));
                        }
                        // if this armor unit controls rendering of this module
                        if (type == spec.slotType) {
                            // then add the part as one we will need to add to render, this way we can ensure
                            // we respect any overrides that might be in a later model part
                            matchedParts.add(name);
                        }
                    }
                }
            }
            for (Map.Entry<OBJModelData, Set<String>> entry : allMatchedParts.entrySet()) {
                Set<String> matchedParts = entry.getValue();
                if (!matchedParts.isEmpty()) {
                    OBJModelData modelData = entry.getKey();
                    Map<ModelPos, Set<String>> quadsToRender = specialQuadsToRender.computeIfAbsent(modelData, _ -> new EnumMap<>(ModelPos.class));
                    //For all the parts we matched, go through and try adding them, while respecting any overrides we might have
                    for (String name : matchedParts) {
                        ModelPos pos = ModelPos.get(name);
                        if (pos == null) {
                            Mekanism.logger.warn("MekaSuit part '{}' is invalid from modules model. Ignoring.", name);
                        } else {
                            //Note: Currently the special quads here for overrides will likely point to our module quads to render
                            // but for consistency and future proofing it is better to make sure we look it up in case overrides gets other stuff
                            // added to it at some point
                            addQuadsToRender(pos, name, overrides, quadsToRender, specialQuadsToRender);
                        }
                    }
                }
            }
        }

        // handle mekatool overrides
        if (type == EquipmentSlot.CHEST) {
            if (hasMekaToolLeft) {
                ignored.addAll(MekanismModelCache.INSTANCE.getOverrideMekaToolParts(true));
            }
            if (hasMekaToolRight) {
                ignored.addAll(MekanismModelCache.INSTANCE.getOverrideMekaToolParts(false));
            }
        }

        Map<ModelPos, Set<String>> armorQuadsToRender = new EnumMap<>(ModelPos.class);
        for (String name : MekanismModelCache.INSTANCE.MEKASUIT.getPartNames()) {
            if (!checkEquipment(type, name)) {
                // skip if it's the wrong equipment type
                continue;
            } else if (name.startsWith(EXCLUSIVE_TAG)) {
                if (wornParts.contains(adjacentType)) {
                    // skip if the part is exclusive and the adjacent part is present
                    continue;
                }
            } else if (name.startsWith(SHARED_TAG) && wornParts.contains(adjacentType) && adjacentType.ordinal() > type.ordinal()) {
                // skip if the part is shared and the shared part already rendered
                continue;
            }
            ModelPos pos = ModelPos.get(name);
            if (pos == null) {
                Mekanism.logger.warn("MekaSuit part '{}' is invalid. Ignoring.", name);
            } else if (!ignored.contains(name)) {
                addQuadsToRender(pos, name, overrides, armorQuadsToRender, specialQuadsToRender);
            }
        }

        Map<ModelPos, PartData> armorQuads = new EnumMap<>(ModelPos.class);
        for (ModelPos pos : ModelPos.VALUES) {
            for (OBJModelData modelData : MekanismModelCache.INSTANCE.MEKASUIT_MODULES) {
                parseTransparency(modelData, pos, armorQuads, specialQuadsToRender.getOrDefault(modelData, Collections.emptyMap()));
            }
            parseTransparency(MekanismModelCache.INSTANCE.MEKASUIT, pos, armorQuads, armorQuadsToRender);
        }
        return armorQuads.isEmpty() ? Collections.emptyMap() : armorQuads;
    }

private static void parseTransparency(OBJModelData modelData, ModelPos pos, Map<ModelPos, PartData> armorQuads, Map<ModelPos, Set<String>> regularQuads) {
        Set<String> allQuads = regularQuads.getOrDefault(pos, Collections.emptySet());
        if (!allQuads.isEmpty()) {
            Set<String> opaqueQuads = new HashSet<>();
            Set<String> opaqueEmissiveQuads = new HashSet<>();
            Set<String> translucentQuads = new HashSet<>();
            PartData partData = armorQuads.computeIfAbsent(pos, _ -> new PartData());
            for (String quad : allQuads) {
                if (quad.contains(GLASS_TAG)) {
                    translucentQuads.add(quad);
                } else if (quad.contains(EMISSIVE_TAG)) {
                    opaqueEmissiveQuads.add(quad);
                } else {
                    opaqueQuads.add(quad);
                }
            }
            //Only add a new entry to our map if we will have any parts. Our getParts method will return empty if there are no quads
            List<BlockStateModelPart> opaqueParts = modelData.getParts(opaqueQuads);
            List<BlockStateModelPart> opaqueEmissiveParts = modelData.getParts(opaqueEmissiveQuads);
            List<BlockStateModelPart> translucentParts = modelData.getParts(translucentQuads);
            if (!opaqueParts.isEmpty()) {
                partData.opaque().addAll(opaqueParts);
            }
            if (!opaqueEmissiveParts.isEmpty()) {
                partData.emissive().addAll(opaqueEmissiveParts);
            }
            if (!translucentParts.isEmpty()) {
                partData.translucent().addAll(translucentParts);
            }
        }
    }

private void submitModel(OrderedSubmitNodeCollector orderedCollector, PoseStack poseStack, List<BlockStateModelPart> parts, int lightCoords, int outlineColor,
              int tintColor, RenderType noTint, RenderType withTint) {
            if (tintColor == CommonColors.WHITE || ARGB.alpha(tintColor) == 0) {
                //If it is white or fully transparent, just render it without tint
                orderedCollector.submitBlockModel(poseStack, noTint, parts, BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY, outlineColor);
                return;
            }
            //Based on submitBlockModel, but using a custom render type and passing a tint color
            PoseStack.Pose pose = poseStack.last().copy();
            if (!withTint.isOutline()) {
                BlockModelFeatureRenderer.Submit submit = new BlockModelFeatureRenderer.Submit(pose, withTint, parts, BlockModelRenderState.EMPTY_TINTS, lightCoords,
                      OverlayTexture.NO_OVERLAY, tintColor, null);
                if (withTint.hasBlending()) {
                    orderedCollector.submitSpecial(RenderPhaseKeys.TRANSLUCENT_BLOCKS_AND_ITEMS, submit);
                } else {
                    orderedCollector.submitSpecial(RenderPhaseKeys.SOLID, submit);
                }
            }
            if (outlineColor != 0) {
                //Note: We don't need to color
                RenderType outlineRenderType = noTint.outline().isPresent() ? noTint.outline().get() : null;
                if (outlineRenderType != null) {
                    orderedCollector.submitSpecial(RenderPhaseKeys.OUTLINE, new BlockModelFeatureRenderer.Submit(pose, outlineRenderType, parts,
                          BlockModelRenderState.EMPTY_TINTS, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, outlineColor, null));
                }
            }
        }

protected void renderArmorPiece(PoseStack poseStack, MultiBufferSource bufferSource, T livingEntity, EquipmentSlot slot, int packedLight, A baseModel, float limbSwing, float limbSwingAmount, float partialTick, float ageInTicks, float netHeadYaw, float headPitch) {
    ItemStack itemstack = livingEntity.getItemBySlot(slot);

    if (itemstack.getItem() instanceof ArmorItem armoritem) {
        if (armoritem.getEquipmentSlot() == slot) {
            Model model = getArmorModelHook(livingEntity, itemstack, slot, baseModel);

            if (!(model instanceof HumanoidModel<?>)) {
                return;
            }

            getParentModel().copyPropertiesTo(baseModel);
            getParentModel().copyPropertiesTo((HumanoidModel<T>) model);

            setPartVisibility(baseModel, slot);
            setPartVisibility((A) model, slot);

            boolean usesInnerModel = usesInnerModel(slot);
            ArmorMaterial armormaterial = armoritem.getMaterial().value();

            IClientItemExtensions extensions = IClientItemExtensions.of(itemstack);
            extensions.setupModelAnimations(livingEntity, itemstack, slot, model, limbSwing, limbSwingAmount, partialTick, ageInTicks, netHeadYaw, headPitch);
            int fallbackColor = extensions.getDefaultDyeColor(itemstack);
            ModelBipedAnimated.setUseMatrixMode(baseModel, true);

            for (int layerIdx = 0; layerIdx < armormaterial.layers().size(); layerIdx++) {
                ArmorMaterial.Layer armormaterial$layer = armormaterial.layers().get(layerIdx);
                int tintColor = extensions.getArmorLayerTintColor(itemstack, livingEntity, armormaterial$layer, layerIdx, fallbackColor);

                if (tintColor != 0) {
                    ResourceLocation texture = ClientHooks.getArmorTexture(livingEntity, itemstack, armormaterial$layer, usesInnerModel, slot);
                    renderModel(poseStack, bufferSource, packedLight, model, tintColor, texture);
                }
            }

            ArmorTrim armortrim = itemstack.get(DataComponents.TRIM);

            if (armortrim != null) {
                ModelBipedAnimated.setUseMatrixMode(baseModel, true);
                ((HumanoidArmorLayerAccess) this).mowziesmobs$renderTrim(armoritem.getMaterial(), poseStack, bufferSource, packedLight, armortrim, model, usesInnerModel);
            }

            if (itemstack.hasFoil()) {
                ModelBipedAnimated.setUseMatrixMode(baseModel, true);
                ((HumanoidArmorLayerAccess) this).mowziesmobs$renderGlint(poseStack, bufferSource, packedLight, model);
            }
        }
    }
}

@Override
    public @NotNull VertexConsumer setUv(float u, float v) {

        float v0 = sprite.getV0();
        float v1 = sprite.getV1();
        float delta = (v - v0) / (v1 - v0);
        if (isInner) {
            delta -= 0.25f;
        }
        delta *= 2f;
        v = Mth.lerp(delta, v0, v1);

        return super.setUv(u, v);
    }

