private void renderArmorLayer(EntityLivingBase living, float limbSwing, float limbSwingAmount, float delta, float age, float headYaw, float headPitch, float scale, EntityEquipmentSlot slot) {
	ItemStack stack = living.getItemStackFromSlot(slot);
	Item item = stack.getItem();
	if (item instanceof ItemArmor) {
		ItemArmor itemarmor = (ItemArmor) item;
		if (itemarmor.getEquipmentSlot() == slot) {
			ArmorRenderer armor = getModel(living, stack, slot, getModelFromSlot(slot));
			armor.setup(living, limbSwing, limbSwingAmount, delta, slot);
			//noinspection ConstantConditions
			rower.bindTexture(getArmorResource(living, stack, slot, null));
			if (itemarmor.hasOverlay(stack)) {
				int rgb = itemarmor.getColor(stack);
				float r = (float) (rgb >> 16 & 255) / 255.0F;
				float g = (float) (rgb >> 8 & 255) / 255.0F;
				float b = (float) (rgb & 255) / 255.0F;
				GlStateManager.color(r, g, b, 1.0F);
				armor.render(living, limbSwing, limbSwingAmount, age, headYaw, headPitch, scale, slot);
				rower.bindTexture(getArmorResource(living, stack, slot, "overlay"));
			}
			GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
			armor.render(living, limbSwing, limbSwingAmount, age, headYaw, headPitch, scale, slot);
			if (stack.hasEffect()) {
				glint.render(living, armor, limbSwing, limbSwingAmount, delta, age, headYaw, headPitch, scale, slot);
			}
		}
	}
}

@Override
public void render(PoseStack poseStack, MultiBufferSource buffer, int packedLight, ArmorStand livingEntity, float limbSwing, float limbSwingAmount, float partialTick, float ageInTicks, float netHeadYaw, float headPitch) {
    SlotTypeReference identifier = CapeItem.getStaticIdentifier();
    AccessoriesCapability accessories = AccessoriesCapability.get(livingEntity);
    if (accessories != null) {
        AccessoriesContainer accessoriesContainer = accessories.getContainer(identifier);
        if (accessoriesContainer != null) {
            ItemStack itemStack = accessoriesContainer.getAccessories().getItem(0);
            if (!itemStack.isEmpty()) {
                if (itemStack.getItem() instanceof CapeItem capeItem) {
                    ResourceLocation texture = capeItem.getCapeTexture();
                    for (Map.Entry<Predicate<ItemStack>, ResourceLocation> entry : AetherClient.CAPE_SECRETS.entrySet()) {
                        if (entry.getKey().test(itemStack)) {
                            texture = entry.getValue();
                            break;
                        }
                    }
                    if (!livingEntity.isInvisible() && texture != null) {
                        ItemStack itemstack = livingEntity.getItemBySlot(EquipmentSlot.CHEST);
                        if (!itemstack.is(Items.ELYTRA)) {
                            poseStack.pushPose();
                            poseStack.translate(0.0F, 0.0F, 0.0925F);
                            poseStack.mulPose(Axis.XP.rotationDegrees(3.0F));
                            poseStack.mulPose(Axis.ZP.rotationDegrees(0.0F));
                            poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
                            VertexConsumer vertexconsumer = buffer.getBuffer(RenderType.entitySolid(texture));
                            this.cape.renderToBuffer(poseStack, vertexconsumer, packedLight, OverlayTexture.NO_OVERLAY);
                            poseStack.popPose();
                        }
                    }
                }
            }
        }
    }
}

	@Override
	public void render(@NotNull PoseStack pose, @NotNull MultiBufferSource buffer, int light, @NotNull ArmorStand armor, float limbSwing, float limbSwingAmount, float partialTick, float ageInTicks, float netHeadYaw, float headPitch) {
		if(!UsesForCursesModule.staticEnabled || !UsesForCursesModule.bindArmorStandsWithPlayerHeads) return;

		ItemStack head = armor.getItemBySlot(EquipmentSlot.HEAD);
		if(head.is(Items.PLAYER_HEAD) && EnchantmentHelper.has(head, EnchantmentEffectComponents.PREVENT_ARMOR_CHANGE)) {

            RenderType rendertype;
            boolean slim = true;
            if (head.has(DataComponents.PROFILE)) {
                GameProfile profile = head.get(DataComponents.PROFILE).gameProfile();
                rendertype = SkullBlockRenderer.getRenderType(SkullBlock.Types.PLAYER, new ResolvableProfile(profile));
                PlayerSkin playerSkin = Minecraft.getInstance().getSkinManager().getInsecureSkin(profile);
                slim = playerSkin.model().equals(PlayerSkin.Model.SLIM);
            } else {
                rendertype =  RenderType.entityTranslucent(DefaultPlayerSkin.getDefaultTexture());
            }
            pose.pushPose();

            if (armor.isBaby()) {
                float s = 1F;
                pose.translate(0F, 0F, 0F);
                pose.scale(s, s, s);
            } else {
                float s = 2F;
                pose.translate(0F, -1.5F, 0F);
                pose.scale(s, s, s);
            }

            PlayerModel<?> model = slim ? playerModelSlim : playerModel;


            model.head.visible = false;
            model.hat.visible = false;

            rotateModel(model.leftArm, armor.getLeftArmPose());
            rotateModel(model.rightArm, armor.getRightArmPose());
            rotateModel(model.leftSleeve, armor.getLeftArmPose());
            rotateModel(model.rightSleeve, armor.getRightArmPose());

            rotateModel(model.leftLeg, armor.getLeftLegPose());
            rotateModel(model.rightLeg, armor.getRightLegPose());
            rotateModel(model.leftPants, armor.getLeftLegPose());
            rotateModel(model.rightPants, armor.getRightLegPose());

            model.renderToBuffer(pose, buffer.getBuffer(rendertype), light, OverlayTexture.NO_OVERLAY, -1);

            pose.popPose();

        }
	}

public void render(PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords, int outlineColor, int tintColor, boolean renderFoil) {
            if (!opaque.isEmpty()) {
                submitModel(nodeCollector, poseStack, opaque, lightCoords, outlineColor, tintColor, NO_TINT, MekanismRenderType.MEKASUIT);
                if (renderFoil) {
                    submitModel(nodeCollector.order(1), poseStack, opaque, lightCoords, EntityRenderState.NO_OUTLINE, tintColor, BASE_GLINT, MekanismRenderType.MEKASUIT_GLINT);
                }
            }
            if (!emissive.isEmpty()) {
                nodeCollector.submitBlockModel(poseStack, EMISSIVE, emissive, BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY, outlineColor);
                if (renderFoil) {
                    nodeCollector.order(1).submitBlockModel(poseStack, BASE_GLINT, emissive, BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY,
                          EntityRenderState.NO_OUTLINE);
                }
            }
            if (!translucent.isEmpty()) {
                nodeCollector.submitBlockModel(poseStack, TRANSLUCENT, translucent, BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY, outlineColor);
                if (renderFoil) {
                    nodeCollector.order(1).submitBlockModel(poseStack, MekanismRenderType.ARMOR_TRANSLUCENT_GLINT, translucent,
                          BlockModelRenderState.EMPTY_TINTS, lightCoords, OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
                }
            }
        }

private static void addQuadsToRender(ModelPos pos, String name, Map<String, OverrideData> overrides, Map<MekaSuitArmor.ModelPos, Set<String>> quadsToRender,
          Map<OBJModelData, Map<ModelPos, Set<String>>> specialQuadsToRender) {
        OverrideData override = overrides.get(name);
        if (override != null) {
            //Update the name and the target quads if there is an override
            name = override.name();
            // Note: In theory the special quads should have our model data corresponding
            // to a map already, but on the off chance they don't compute and add it
            OBJModelData overrideData = override.modelData();
            quadsToRender = specialQuadsToRender.computeIfAbsent(overrideData, _ -> new EnumMap<>(ModelPos.class));
        }
        quadsToRender.computeIfAbsent(pos, _ -> new HashSet<>()).add(name);
    }
